descriptor.controllerScript:
self.onInit = function () {
  // Inject Tailwind
  if (!document.getElementById('tailwindcss')) {
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => self.ctx.detectChanges();
    document.head.appendChild(script);
  }

  const percentKeys = ['cpu_usage', 'ram_usage']; // raw fraction
  const floatKeys = ['flash_usage', 'device_temperature']; // already in 0-100 range
  const textKeys = ['imei', 'sim_iccid', 'mac_address'];

  [...percentKeys, ...floatKeys, ...textKeys].forEach(key => {
    self[key] = key.includes('usage') || key.includes('temperature') ? 0 : '';
  });

  self.onDataUpdated = function () {
    self.ctx.data.forEach(({ dataKey, data }) => {
      const key = dataKey.name;
      const value = data.at(-1)?.[1];

      if (value !== undefined) {
        if (percentKeys.includes(key)) {
          self[key] = (parseFloat(value) * 100).toFixed(2);
        } else if (floatKeys.includes(key)) {
          self[key] = parseFloat(value).toFixed(2);
        } else if (textKeys.includes(key)) {
          self[key] = value;
        }
      }
    });
  };
};

